p03-exchange-balance:
def solve(
    a: float,
    b: float,
    c: float,
    u: float,
    amounts: list[float],
) -> tuple[list[list[float]], list[float], float]:
    return exchange(a,b,c,u,amounts)

def exchange(a, b, c, u, amounts):
    matrix = [[-a-c, b], [a, -b]]
    first, second = amounts
    rates = [u-(a+c)*first+b*second, a*first-b*second]
    return matrix, rates, sum(rates)

p03-projection:
def solve(
    vector: list[float],
    direction: list[float],
) -> tuple[float, float, list[float], list[float]]:
    return projection(vector,direction)

def projection(vector, direction):
    import math
    dot = sum(x*y for x, y in zip(vector, direction))
    length = math.sqrt(sum(x*x for x in vector))
    scale = dot / sum(y*y for y in direction)
    projected = [scale*y for y in direction]
    residual = [x-y for x, y in zip(vector, projected)]
    return dot, length, projected, residual

p03-open-equilibrium:
def solve(
    a: float,
    b: float,
    c: float,
    u: float,
) -> list[float]:
    return open_equilibrium(a,b,c,u)

def open_equilibrium(a, b, c, u):
    first = u/c
    return [first, a*first/b]

p03-damped:
def solve(
    alpha: float,
    omega: float,
    initial: list[float],
    times: list[float],
) -> tuple[list[list[float]], list[list[float]]]:
    return damped(alpha,omega,initial,times)

def damped(alpha, omega, initial, times):
    import math
    values = []
    for t in times:
        co, si, decay = math.cos(omega*t), math.sin(omega*t), math.exp(-alpha*t)
        values.append([decay*(co*initial[0]-si*initial[1]),
                       decay*(si*initial[0]+co*initial[1])])
    return [[-alpha, omega], [-alpha, -omega]], values

p03-jordan:
def solve(
    rate: float,
    coupling: float,
    initial: list[float],
    times: list[float],
) -> list[list[float]]:
    return jordan(rate,coupling,initial,times)

def jordan(rate, coupling, initial, times):
    import math
    return [[math.exp(-rate*t)*(initial[0]+coupling*t*initial[1]),
             math.exp(-rate*t)*initial[1]] for t in times]

p03-scaled-field:
def solve(
    matrix: list[list[float]],
    points: list[list[float]],
    multiplier: float,
) -> tuple[list[list[float]], list[list[float]], list[float]]:
    return scaled_field(matrix,points,multiplier)

def scaled_field(matrix, points, multiplier):
    import math
    original = [[sum(row[j]*point[j] for j in range(2)) for row in matrix] for point in points]
    scaled = [[multiplier*x for x in row] for row in original]
    speeds = [math.sqrt(sum(x*x for x in row)) for row in scaled]
    return original, scaled, speeds

p03-closed-state:
def solve(
    a: float,
    b: float,
    initial: list[float],
    times: list[float],
) -> list[list[float]]:
    return closed_state(a,b,initial,times)

def closed_state(a, b, initial, times):
    import math
    total = sum(initial)
    if a+b == 0:
        return [list(initial) for _ in times]
    states = []
    for t in times:
        remaining = math.exp(-(a+b)*t)
        transferred = -math.expm1(-(a+b)*t)
        states.append([initial[0]*remaining+total*(b/(a+b))*transferred,
                       initial[1]*remaining+total*(a/(a+b))*transferred])
    return states

p03-chain-rate:
def solve(
    state: list[float],
    rates: list[float],
) -> tuple[list[float], float]:
    return gradient_rate(state,rates)

def gradient_rate(state, rates):
    gradient = list(state)
    return gradient, sum(x*y for x, y in zip(gradient, rates))
